            }
            88% {
                opacity: var(--fl-max-opacity, 0.7);
            }
            100% {
                transform: translate3d(-10vw, -10vh, 0) rotate(-340deg) scale(0.8);
                opacity: 0;
            }
        }

        @keyframes summerFlowerBreeze3 {
            0% {
                transform: translate3d(18vw, 105vh, 0) rotate(15deg) scale(0.7);
                opacity: 0;
            }
            15% {
                opacity: var(--fl-max-opacity, 0.55);
