            }
            88% {
                opacity: var(--fl-max-opacity, 0.55);
            }
            100% {
                transform: translate3d(36vw, -10vh, 0) rotate(325deg) scale(0.75);
                opacity: 0;
            }
        }

        @keyframes summerFlowerBreeze4 {
            0% {
                transform: translate3d(52vw, 105vh, 0) rotate(-25deg) scale(0.8);
                opacity: 0;
            }
            12% {
