            box-shadow: 0 4px 14px rgba(29, 78, 216, 0.35) !important;
        }
        [data-theme-id="17"] #floating-bottom-nav .nav-item:hover svg,
        [data-theme-id="17"] #floating-bottom-nav .nav-item.active svg {
            color: #FFFFFF !important;
        }
        [data-theme-id="17"] #musicToggleBtn {
            background: #1D4ED8 !important;
            border: 2px solid #FFFFFF !important;
            box-shadow: 0 4px 16px rgba(29, 78, 216, 0.4) !important;
        }

        /* Ethereal Animations */
        @keyframes ethereal-pulse {
            0%, 100% { transform: scale(1); filter: drop-shadow(0 10px 25px rgba(29, 78, 216, 0.18)); }
            50% { transform: scale(1.025); filter: drop-shadow(0 14px 32px rgba(29, 78, 216, 0.28)); }
        }
        @keyframes ethereal-sway {
            0%, 100% { transform: rotate(-2deg); }
            50% { transform: rotate(2deg); }
        }
        @keyframes ethereal-float {
            0%, 100% { transform: translateY(0); }
            50% { transform: translateY(-6px); }
        }
        .anim-ethereal-pulse { animation: ethereal-pulse 4s ease-in-out infinite; }
        .anim-ethereal-sway { animation: ethereal-sway 4.5s ease-in-out infinite; }
        .anim-ethereal-float { animation: ethereal-float 3.5s ease-in-out infinite; }

        /* Theme 17 Ethereal Bloom Floating Blue Leaves & Petals Ambient Animation */
        .ethereal-floating-particle {
            position: absolute;
            pointer-events: none;
            will-change: transform, opacity;
            animation-iteration-count: infinite;
            animation-timing-function: ease-in-out;
        }

        .ethereal-orbit-1 { animation-name: etherealOrbit1; }
        .ethereal-orbit-2 { animation-name: etherealOrbit2; }
        .ethereal-orbit-3 { animation-name: etherealOrbit3; }
        .ethereal-orbit-4 { animation-name: etherealOrbit4; }
        .ethereal-orbit-5 { animation-name: etherealOrbit5; }
        .ethereal-orbit-6 { animation-name: etherealOrbit6; }

        /* Path 1: Clockwise wide orbit across top & right with gentle tumbling */
        @keyframes etherealOrbit1 {
            0% {
                transform: translate3d(-5vw, 20vh, 0) rotate(0deg) scale(0.7);
                opacity: 0;
            }
            10% { opacity: var(--eth-max-opacity, 0.75); }
            30% { transform: translate3d(35vw, 8vh, 0) rotate(110deg) scale(0.9); }
            60% { transform: translate3d(85vw, 35vh, 0) rotate(220deg) scale(1); }
            85% { transform: translate3d(60vw, 85vh, 0) rotate(310deg) scale(0.85); opacity: var(--eth-max-opacity, 0.75); }
            100% { transform: translate3d(-10vw, 95vh, 0) rotate(420deg) scale(0.7); opacity: 0; }
        }

        /* Path 2: Counter-clockwise sweeping orbit from bottom-right up and across left */
        @keyframes etherealOrbit2 {
            0% {
                transform: translate3d(105vw, 80vh, 0) rotate(0deg) scale(0.8);
                opacity: 0;
            }
            12% { opacity: var(--eth-max-opacity, 0.7); }
            35% { transform: translate3d(75vw, 25vh, 0) rotate(-120deg) scale(1.05); }
            65% { transform: translate3d(20vw, 15vh, 0) rotate(-240deg) scale(0.9); }
            85% { transform: translate3d(5vw, 65vh, 0) rotate(-330deg) scale(0.95); opacity: var(--eth-max-opacity, 0.7); }
            100% { transform: translate3d(80vw, 105vh, 0) rotate(-420deg) scale(0.75); opacity: 0; }
        }

        /* Path 3: Figure-8 / Swirling loop around center */
        @keyframes etherealOrbit3 {
            0% {
                transform: translate3d(15vw, 105vh, 0) rotate(25deg) scale(0.75);
                opacity: 0;
            }
            15% { opacity: var(--eth-max-opacity, 0.65); }
            35% { transform: translate3d(65vw, 65vh, 0) rotate(140deg) scale(0.95); }
            55% { transform: translate3d(30vw, 40vh, 0) rotate(260deg) scale(1.05); }
            75% { transform: translate3d(80vw, 18vh, 0) rotate(340deg) scale(0.85); }
            90% { opacity: var(--eth-max-opacity, 0.65); }
            100% { transform: translate3d(45vw, -8vh, 0) rotate(420deg) scale(0.7); opacity: 0; }
        }

        /* Path 4: Spiral ascent from lower-left circling towards upper-right */
        @keyframes etherealOrbit4 {
            0% {
                transform: translate3d(-8vw, 75vh, 0) rotate(-30deg) scale(0.7);
                opacity: 0;
            }
            12% { opacity: var(--eth-max-opacity, 0.8); }
            30% { transform: translate3d(40vw, 82vh, 0) rotate(80deg) scale(0.9); }
            55% { transform: translate3d(70vw, 50vh, 0) rotate(190deg) scale(1); }
            75% { transform: translate3d(35vw, 20vh, 0) rotate(290deg) scale(0.85); }
            90% { opacity: var(--eth-max-opacity, 0.8); }
            100% { transform: translate3d(95vw, -10vh, 0) rotate(390deg) scale(0.75); opacity: 0; }
        }

        /* Path 5: Diagonal swirling cascade from top-right to bottom-left */
        @keyframes etherealOrbit5 {
            0% {
                transform: translate3d(95vw, -5vh, 0) rotate(10deg) scale(0.85);
                opacity: 0;
            }
            15% { opacity: var(--eth-max-opacity, 0.7); }
            40% { transform: translate3d(50vw, 35vh, 0) rotate(150deg) scale(1); }
            70% { transform: translate3d(15vw, 70vh, 0) rotate(270deg) scale(0.9); }
            88% { opacity: var(--eth-max-opacity, 0.7); }
            100% { transform: translate3d(-10vw, 105vh, 0) rotate(370deg) scale(0.75); opacity: 0; }
        }

        /* Path 6: Horizontal undulating breeze across middle with gentle spins */
        @keyframes etherealOrbit6 {
            0% {
                transform: translate3d(-10vw, 45vh, 0) rotate(0deg) scale(0.75);
                opacity: 0;
            }
            15% { opacity: var(--eth-max-opacity, 0.6); }
            35% { transform: translate3d(28vw, 30vh, 0) rotate(90deg) scale(0.95); }
            65% { transform: translate3d(65vw, 55vh, 0) rotate(210deg) scale(1); }
            85% { transform: translate3d(92vw, 38vh, 0) rotate(300deg) scale(0.85); opacity: var(--eth-max-opacity, 0.6); }
            100% { transform: translate3d(110vw, 48vh, 0) rotate(380deg) scale(0.75); opacity: 0; }
        }

