        /* ================= THEME 4: BASIC WANTED POSTER BESPOKE STYLES ================= */
        @import url('https://fonts.googleapis.com/css2?family=Pirata+One&family=Playfair+Display:ital,wght@0,400..900;1,400..900&family=Plus+Jakarta+Sans:wght@300;400;500;600;700&display=swap');

        .font-wanted-gothic {
            font-family: 'Pirata One', Georgia, serif !important;
            letter-spacing: 0.05em;
        }
        .font-wanted-serif {
            font-family: 'Playfair Display', Georgia, serif !important;
        }
        .font-wanted-body {
            font-family: 'Plus Jakarta Sans', sans-serif !important;
        }

        /* Animations: Dari kecil ke membesar, dari kanan ke kiri, stamp slam */
        @keyframes wantedZoomIn {
            0% { opacity: 0; transform: scale(0.65); }
            60% { opacity: 1; transform: scale(1.04); }
            100% { opacity: 1; transform: scale(1); }
        }
        @keyframes wantedSlideFromRight {
            0% { opacity: 0; transform: translateX(70px); }
            100% { opacity: 1; transform: translateX(0); }
        }
        @keyframes wantedScaleSlideRight {
            0% { opacity: 0; transform: scale(0.7) translateX(60px); }
            70% { opacity: 1; transform: scale(1.03) translateX(-6px); }
            100% { opacity: 1; transform: scale(1) translateX(0); }
        }
        @keyframes wantedStampSlam {
            0% { opacity: 0; transform: scale(3.2) rotate(-26deg); filter: blur(3px); }
            45% { opacity: 0.95; transform: scale(0.92) rotate(-6deg); filter: blur(0px); }
            70% { opacity: 1; transform: scale(1.05) rotate(-9deg); }
            100% { opacity: 1; transform: scale(1) rotate(-8deg); }
        }
        @keyframes wantedStardustPulse {
            0% { opacity: 0.35; transform: scale(0.9) translateY(0); }
            50% { opacity: 0.85; transform: scale(1.1) translateY(-4px); }
            100% { opacity: 0.35; transform: scale(0.9) translateY(0); }
        }

        .anim-wanted-zoom { animation: wantedZoomIn 0.9s cubic-bezier(0.16, 1, 0.3, 1) both; }
        .anim-wanted-slide { animation: wantedSlideFromRight 0.9s cubic-bezier(0.16, 1, 0.3, 1) both; }
        .anim-wanted-combo { animation: wantedScaleSlideRight 1s cubic-bezier(0.16, 1, 0.3, 1) both; }
        .anim-wanted-stamp { animation: wantedStampSlam 0.65s cubic-bezier(0.2, 0.8, 0.2, 1.2) both; animation-delay: 0.3s; }
        .anim-wanted-stardust { animation: wantedStardustPulse 3.5s ease-in-out infinite; }

