        /* ================= THEME 9 (BASIC WHISPERING GARDEN) ================= */
        @import url('https://fonts.googleapis.com/css2?family=Great+Vibes&display=swap');

        .font-garden-serif {
            font-family: 'Playfair Display', Georgia, serif;
        }
        .font-garden-script {
            font-family: 'Great Vibes', cursive;
        }
