            font-family: 'Plus Jakarta Sans', system-ui, -apple-system, sans-serif;
        }

        /* Animations */
        @keyframes gardenZoomIn {
            0% { opacity: 0; transform: scale(0.85); }
            100% { opacity: 1; transform: scale(1); }
        }
        @keyframes gardenSlideIn {
            0% { opacity: 0; transform: translateX(50px); }
            100% { opacity: 1; transform: translateX(0); }
        }
        @keyframes gardenSlideUp {
            0% { opacity: 0; transform: translateY(40px); }
            100% { opacity: 1; transform: translateY(0); }
        }
        @keyframes gardenButterflyFlutter {
            0%, 100% { transform: translateY(0) rotate(0deg) scale(1); }
            25% { transform: translateY(-8px) rotate(4deg) scale(1.05); }
            50% { transform: translateY(-14px) rotate(-3deg) scale(0.98); }
            75% { transform: translateY(-6px) rotate(2deg) scale(1.03); }
        }
        @keyframes gardenTreeSway {
            0%, 100% { transform: rotate(0deg); }
            50% { transform: rotate(1.2deg); }
        }

        .anim-garden-zoom {
            animation: gardenZoomIn 1s cubic-bezier(0.16, 1, 0.3, 1) forwards;
        }
        .anim-garden-slide {
            animation: gardenSlideIn 1s cubic-bezier(0.16, 1, 0.3, 1) forwards;
        }
        .anim-garden-up {
            animation: gardenSlideUp 1s cubic-bezier(0.16, 1, 0.3, 1) forwards;
        }
        .anim-garden-butterfly {
            animation: gardenButterflyFlutter 6s ease-in-out infinite;
        }
        .anim-garden-sway {
            transform-origin: bottom center;
            animation: gardenTreeSway 8s ease-in-out infinite;
        }

        /* Canvas & Scrollable Content */
        [data-theme-id="9"] #invitation-main-content,
