        }
        @keyframes sunnySlideInRight {
            0% { opacity: 0; transform: translateX(50px); }
            100% { opacity: 1; transform: translateX(0); }
        }
        @keyframes sunnySlideInLeft {
            0% { opacity: 0; transform: translateX(-50px); }
            100% { opacity: 1; transform: translateX(0); }
        }
        @keyframes sunnySlideUp {
            0% { opacity: 0; transform: translateY(35px); }
            100% { opacity: 1; transform: translateY(0); }
        }
        @keyframes sunnyFoliageSway {
            0%, 100% { transform: rotate(0deg); }
            50% { transform: rotate(1.8deg); }
        }
        @keyframes sunnyPulseGlow {
            0%, 100% { transform: scale(1); box-shadow: 0 4px 15px rgba(230, 126, 34, 0.2); }
            50% { transform: scale(1.02); box-shadow: 0 8px 25px rgba(230, 126, 34, 0.35); }
        }

        .anim-sunny-zoom {
            animation: sunnyZoomIn 1s cubic-bezier(0.16, 1, 0.3, 1) forwards;
        }
        .anim-sunny-slide {
            animation: sunnySlideInRight 0.9s cubic-bezier(0.16, 1, 0.3, 1) forwards;
        }
        .anim-sunny-slide-left {
            animation: sunnySlideInLeft 0.9s cubic-bezier(0.16, 1, 0.3, 1) forwards;
        }
        .anim-sunny-up {
            animation: sunnySlideUp 0.9s cubic-bezier(0.16, 1, 0.3, 1) forwards;
        }
        .anim-sunny-sway {
            transform-origin: top center;
            animation: sunnyFoliageSway 7s ease-in-out infinite;
        }
        .anim-sunny-pulse {
            animation: sunnyPulseGlow 3s ease-in-out infinite;
        }

