        /* Multiple Mini Paper Airplanes Flying Randomly Across Theme */
        .crayon-mini-plane {
            position: fixed;
            top: 0;
            left: 0;
            pointer-events: none;
            z-index: 38;
            will-change: transform;
            filter: drop-shadow(0 3px 6px rgba(232, 90, 79, 0.22));
            animation-iteration-count: infinite;
            animation-timing-function: cubic-bezier(0.42, 0, 0.58, 1);
        }
        .plane-flight-1 { animation-name: crayonPlaneFlight1; }
        .plane-flight-2 { animation-name: crayonPlaneFlight2; }
        .plane-flight-3 { animation-name: crayonPlaneFlight3; }
        .plane-flight-4 { animation-name: crayonPlaneFlight4; }
        .plane-flight-5 { animation-name: crayonPlaneFlight5; }
        .plane-flight-6 { animation-name: crayonPlaneFlight6; }

        @keyframes crayonPlaneFlight1 {
            0% {
                transform: translate3d(-12vw, 95vh, 0) rotate(28deg) scale(0.85);
                opacity: 0;
            }
            5% {
                opacity: 0.95;
            }
            25% {
                transform: translate3d(22vw, 68vh, 0) rotate(14deg) scale(1);
            }
            48% {
                transform: translate3d(52vw, 52vh, 0) rotate(24deg) scale(0.92);
            }
            72% {
                transform: translate3d(78vw, 26vh, 0) rotate(10deg) scale(1.05);
            }
            92% {
                opacity: 0.95;
            }
            100% {
                transform: translate3d(112vw, -12vh, 0) rotate(32deg) scale(0.88);
                opacity: 0;
            }
        }

        @keyframes crayonPlaneFlight2 {
            0% {
                transform: translate3d(110vw, 8vh, 0) scaleX(-1) rotate(18deg) scale(0.8);
                opacity: 0;
            }
            6% {
                opacity: 0.92;
            }
            30% {
                transform: translate3d(72vw, 32vh, 0) scaleX(-1) rotate(26deg) scale(0.95);
            }
            55% {
                transform: translate3d(40vw, 58vh, 0) scaleX(-1) rotate(12deg) scale(1);
            }
            80% {
                transform: translate3d(14vw, 76vh, 0) scaleX(-1) rotate(22deg) scale(0.9);
            }
            94% {
                opacity: 0.92;
            }
            100% {
                transform: translate3d(-14vw, 96vh, 0) scaleX(-1) rotate(28deg) scale(0.85);
                opacity: 0;
            }
        }

        @keyframes crayonPlaneFlight3 {
            0% {
                transform: translate3d(-10vw, 38vh, 0) rotate(12deg) scale(0.9);
                opacity: 0;
            }
            6% {
                opacity: 0.95;
            }
            25% {
                transform: translate3d(24vw, 56vh, 0) rotate(25deg) scale(1);
            }
            50% {
                transform: translate3d(58vw, 34vh, 0) rotate(-6deg) scale(0.95);
            }
            75% {
                transform: translate3d(84vw, 48vh, 0) rotate(18deg) scale(1.02);
            }
            93% {
                opacity: 0.95;
            }
            100% {
                transform: translate3d(114vw, 32vh, 0) rotate(8deg) scale(0.9);
                opacity: 0;
            }
        }

        @keyframes crayonPlaneFlight4 {
            0% {
