        window.greetAtPendopo = function() {
            const bubble = document.getElementById('pendopo-bubble');
            if (bubble) {
                bubble.style.opacity = '1';
                bubble.style.transform = 'translateX(-50%) scale(1)';
                bubble.style.pointerEvents = 'auto';
                showToast('{{ $groomNickname }} & {{ $brideNickname }}: "Sampai jumpa di hari bahagia kami di depan pendopo!" 🏡✨');
                setTimeout(() => {
                    bubble.style.opacity = '0';
                    bubble.style.transform = 'translateX(-50%) scale(0.9)';
                    bubble.style.pointerEvents = 'none';
                }, 4000);
            }
        };

        window.downloadIcsEvent = function(type) {
            const isAkad = (type === 'akad');
            const isNgunduh = (type === 'ngunduh');
            const title = isAkad
                ? "Akad Nikah: {{ $groomNickname }} & {{ $brideNickname }}"
                : (isNgunduh ? "Ngunduh Mantu: {{ $groomNickname }} & {{ $brideNickname }}" : "Resepsi Pernikahan: {{ $groomNickname }} & {{ $brideNickname }}");
            const loc = isAkad ? "{{ $akadAddress ?? $venueAddress }}" : (isNgunduh ? "Rumah Mempelai Pria, Unduh Mantu" : "{{ $venueAddress }}");
            const dtStart = isAkad ? "20260930T080000" : (isNgunduh ? "20260830T080000" : "20260930T122500");
            const dtEnd = isAkad ? "20260930T110000" : (isNgunduh ? "20260830T200000" : "20260930T160000");
            const icsData = [
                "BEGIN:VCALENDAR",
                "VERSION:2.0",
                "PRODID:-//SimpulTemu//Wedding Invitation//EN",
                "BEGIN:VEVENT",
                "SUMMARY:" + title,
                "DESCRIPTION:Pernikahan {{ $groomName }} & {{ $brideName }}",
                "LOCATION:" + loc,
                "DTSTART:" + dtStart,
                "DTEND:" + dtEnd,
                "END:VEVENT",
                "END:VCALENDAR"
            ].join("\r\n");
            const blob = new Blob([icsData], { type: 'text/calendar;charset=utf-8' });
            const link = document.createElement('a');
            link.href = window.URL.createObjectURL(blob);
            link.setAttribute('download', `${type}-event.ics`);
            document.body.appendChild(link);
            link.click();
            document.body.removeChild(link);
            showToast('File Apple Calendar (.ics) berhasil diunduh! 📅');
        };

        function updateNostalgicCar() {
            const road = document.getElementById('section-coastal-road');
            const car = document.getElementById('nostalgic-wagon-car');
            if (!road || !car) return;

            const rect = road.getBoundingClientRect();
            const windowH = window.innerHeight || document.documentElement.clientHeight;

            // Progress is 0 when road enters bottom of screen, 1 when it leaves top of screen
            const totalTravel = windowH + rect.height;
            const currentTravel = windowH - rect.top;
            const progress = Math.max(0, Math.min(1, currentTravel / totalTravel));

            // Road width minus car width
            const roadWidth = road.offsetWidth;
            const carWidth = car.offsetWidth || 100;
            const maxDriveX = Math.max(50, roadWidth - carWidth - 16);

            const targetX = progress * maxDriveX;
            const bounceY = Math.sin(progress * 28) * 1.5;

            car.style.transform = `translateX(${targetX}px) translateY(${bounceY}px)`;
        }

        window.smoothScrollTo = function(e, id) {
            e.preventDefault();
            const el = document.getElementById(id);
            if (el) {
                el.scrollIntoView({ behavior: 'smooth', block: 'start' });
            }
        };

        window.sendWhatsAppRSVP3 = function() {
            const name = document.getElementById('rsvp_guest_name_3')?.value || 'Tamu Undangan';
            const count = document.getElementById('rsvp_guest_count_3')?.value || '1';
            const status = document.querySelector('input[name="rsvp_status_3"]:checked')?.value || 'Hadir';
            const groom = "{{ $groomNickname }}";
            const bride = "{{ $brideNickname }}";
            const text = `Halo ${groom} & ${bride}, saya ${name} mengonfirmasi kehadiran di pernikahan kalian: ${status} (${count} orang). Terima kasih!`;
            const phone = "{{ $invitation->contact_phone ?? '6281234567890' }}";
            window.open(`https://wa.me/${phone}?text=${encodeURIComponent(text)}`, '_blank');
        };

        // ================= GLOBAL REAL-TIME RSVP & UCAPAN HANDLER FOR ALL THEMES =================
        document.addEventListener('DOMContentLoaded', function () {
            const rsvpForms = document.querySelectorAll('form[data-rsvp-form], #section-rsvp form');
            
            rsvpForms.forEach(form => {
                form.addEventListener('submit', async function (e) {
                    e.preventDefault();

                    const submitBtn = form.querySelector('button[type="submit"]');
                    const originalBtnContent = submitBtn ? submitBtn.innerHTML : '';
                    if (submitBtn) {
                        submitBtn.disabled = true;
                        submitBtn.classList.add('opacity-75', 'cursor-not-allowed');
                        submitBtn.innerHTML = `
                            <span class="inline-flex items-center justify-center gap-2">
                                <svg class="animate-spin h-4 w-4" viewBox="0 0 24 24" fill="none">
                                    <circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle>
                                    <path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8v8H4z"></path>
                                </svg>
                                <span>Mengirimkan...</span>
                            </span>
                        `;
                    }

                    const formData = new FormData(form);
                    @if(isset($isDemo) && $isDemo)
                    formData.append('is_demo', '1');
                    @endif

                    try {
                        const token = document.querySelector('meta[name="csrf-token"]')?.getAttribute('content') 
                            || form.querySelector('input[name="_token"]')?.value 
                            || '';

                        const response = await fetch(form.action, {
                            method: 'POST',
                            headers: {
                                'Accept': 'application/json',
                                'X-Requested-With': 'XMLHttpRequest',
                                'X-CSRF-TOKEN': token,
                                @if(isset($isDemo) && $isDemo)
                                'X-Is-Demo': '1',
                                @endif
                            },
                            body: formData
                        });

                        const resData = await response.json().catch(() => null);

                        if (response.ok && resData && resData.success) {
                            showToast(resData.message || 'Konfirmasi & ucapan Anda berhasil dikirim!');

                            // If a comment message was provided, prepend into comment feed
                            if (resData.comment && resData.comment.message) {
                                const section = form.closest('#section-rsvp') || document;
                                const feed = section.querySelector('[data-comments-feed]') || document.querySelector('[data-comments-feed]');
                                
                                if (feed) {
                                    const list = feed.querySelector('[data-comments-list]');
                                    const countBadge = feed.querySelector('[data-comments-count]');
                                    const emptyState = feed.querySelector('[data-comments-empty]');
                                    const template = feed.querySelector('template[data-comment-template]');

                                    if (emptyState) {
                                        emptyState.classList.add('hidden');
                                        emptyState.style.display = 'none';
                                    }

                                    if (countBadge) {
                                        const countNum = parseInt((countBadge.textContent.match(/\d+/) || [0])[0], 10) + 1;
                                        countBadge.textContent = `${countNum} Pesan`;
                                    }

                                    if (list && template) {
                                        const clone = template.content.cloneNode(true);
                                        const nameEl = clone.querySelector('[data-comment-name]');
                                        const timeEl = clone.querySelector('[data-comment-time]');
                                        const msgEl = clone.querySelector('[data-comment-message]');

                                        if (nameEl) nameEl.textContent = resData.comment.name;
                                        if (timeEl) timeEl.textContent = resData.comment.time_ago || 'Baru saja';
                                        if (msgEl) msgEl.textContent = `"${resData.comment.message}"`;

                                        const firstItem = clone.firstElementChild;
                                        if (firstItem) {
                                            firstItem.classList.add('ring-2', 'ring-emerald-400/50');
                                            setTimeout(() => {
                                                firstItem.classList.remove('ring-2', 'ring-emerald-400/50');
                                            }, 2500);
                                        }

                                        list.insertBefore(clone, list.firstChild);
                                        list.scrollTop = 0;
                                    }
                                }
                            }

                            // Reset message textarea
                            const messageArea = form.querySelector('textarea[name="message"]');
                            if (messageArea) messageArea.value = '';

                        } else {
                            const errMessage = resData?.message 
                                || (resData?.errors ? Object.values(resData.errors).flat().join(', ') : null)
                                || 'Gagal mengirim konfirmasi. Silakan coba lagi.';
                            showToast(errMessage);
                        }
                    } catch (err) {
                        console.error('RSVP AJAX Error:', err);
                        showToast('Gagal menghubungi server. Mohon periksa koneksi Anda.');
                    } finally {
                        if (submitBtn) {
                            submitBtn.disabled = false;
                            submitBtn.classList.remove('opacity-75', 'cursor-not-allowed');
                            submitBtn.innerHTML = originalBtnContent;
                        }
                    }
                });
            });
        });

        // ================= INTERACTIVE SCROLL & PARALLAX ENGINE FOR THEME 13 & FLOATING DOCK =================
        (function() {
            const themeId = document.body.getAttribute('data-theme-id');
            const isTheme13 = (themeId === '13');

            // 1. Scrollspy for Floating Bottom Nav Dock
            const sections = [
                { id: 'section-hero', el: document.getElementById('section-hero') },
                { id: 'section-mempelai', el: document.getElementById('section-mempelai') },
                { id: 'section-acara', el: document.getElementById('section-acara') },
                { id: 'section-kutipan', el: document.getElementById('section-kutipan') },
                @if($invitation->show_love_story ?? true)
                { id: 'section-cerita', el: document.getElementById('section-cerita') },
                @endif
                { id: 'section-galeri', el: document.getElementById('section-galeri') },
                { id: 'section-hadiah', el: document.getElementById('section-hadiah') },
                { id: 'section-rsvp', el: document.getElementById('section-rsvp') }
            ].filter(s => s.el !== null);

            const navLinks = document.querySelectorAll('#floating-bottom-nav .nav-item');

            function updateScrollspy() {
                const scrollPos = window.scrollY || document.documentElement.scrollTop;
                let activeId = '';

                for (let i = sections.length - 1; i >= 0; i--) {
                    const sec = sections[i];
                    if (sec.el.offsetTop - 220 <= scrollPos) {
                        activeId = sec.id;
                        break;
                    }
                }

                if (!activeId && sections.length > 0) {
                    activeId = sections[0].id;
                }

                if (activeId && navLinks.length > 0) {
                    navLinks.forEach(link => {
                        const href = link.getAttribute('href') || '';
                        const onclick = link.getAttribute('onclick') || '';
                        if (href.includes(activeId) || onclick.includes(activeId)) {
                            link.classList.add('active');
                        } else {
                            link.classList.remove('active');
                        }
                    });
                }
            }

            // 2. Parallax Motion for Theme 13
            const t13Sidebar = document.getElementById('t13-desktop-sidebar');
            const cloudTR = t13Sidebar ? t13Sidebar.querySelector('.anim-summer-cloud') : null;
            const cloudBL = t13Sidebar ? t13Sidebar.querySelector('.anim-summer-cloud-alt') : null;
            const ampersand = t13Sidebar ? t13Sidebar.querySelector('.anim-summer-sway') : null;
            const flowerTL = t13Sidebar ? t13Sidebar.querySelector('.anim-summer-flower-tl') : null;
            const flowerTR = t13Sidebar ? t13Sidebar.querySelector('.anim-summer-flower-tr') : null;

            function updateTheme13Parallax() {
                if (!t13Sidebar || window.innerWidth < 768) return;
                const scrolled = window.scrollY || document.documentElement.scrollTop;

                if (cloudTR) {
                    const trShiftY = -scrolled * 0.04;
                    const trShiftX = Math.sin(scrolled * 0.002) * 8;
                    cloudTR.style.transform = `translate(${trShiftX}px, ${trShiftY}px)`;
                }

                if (cloudBL) {
                    const blShiftY = scrolled * 0.03;
                    const blShiftX = -Math.sin(scrolled * 0.002) * 8;
                    cloudBL.style.transform = `translate(${blShiftX}px, ${blShiftY}px)`;
                }

                if (ampersand) {
                    const swayY = Math.sin(scrolled * 0.004) * 6;
                    const swayRot = Math.sin(scrolled * 0.003) * 3;
                    ampersand.style.transform = `translateY(${swayY}px) rotate(${swayRot}deg)`;
                }

                if (flowerTL) {
                    flowerTL.style.transform = `rotate(${Math.sin(scrolled * 0.0025) * 4}deg)`;
                }
                if (flowerTR) {
                    flowerTR.style.transform = `rotate(${-Math.sin(scrolled * 0.0025) * 4}deg)`;
                }
            }

            let ticking = false;
            function onScrollHandler() {
                if (!ticking) {
                    window.requestAnimationFrame(function() {
                        updateScrollspy();
                        if (isTheme13) updateTheme13Parallax();
                        if (typeof updateNostalgicCar === 'function') updateNostalgicCar();
                        ticking = false;
                    });
                    ticking = true;
                }
            }

            window.addEventListener('scroll', onScrollHandler, { passive: true });
            const mainContentEl = document.getElementById('invitation-main-content');
            if (mainContentEl) {
                mainContentEl.addEventListener('scroll', onScrollHandler, { passive: true });
            }

            document.addEventListener('DOMContentLoaded', function() {
                updateScrollspy();
                if (isTheme13) updateTheme13Parallax();
                if (typeof updateNostalgicCar === 'function') updateNostalgicCar();
            });
        })();
    </script>
